# ruff: noqa: SLF001

from pathlib import Path

import pytest
import yaml

from utils import scenarios
from utils.scripts import update_mirror_images


def _write_lock(lock_path: Path) -> str:
    content = """\
# Auto-generated by: uv run bin/mirror_images.py lock
# Do not edit manually.
version: 1
images:
  datadog/agent:latest:
    digest: sha256:old-agent
    target: registry.ddbuild.io/system-tests/mirror/datadog/agent:latest
    tag: 7.80.1
  redis:7:
    digest: sha256:redis
    target: registry.ddbuild.io/system-tests/mirror/redis:7
    tag: '7'
"""
    lock_path.write_text(content, encoding="utf-8")
    return content


@scenarios.test_the_test
class Test_UpdateMirrorImages:
    def test_parse_refresh(self):
        assert update_mirror_images._parse_refresh(None) is None
        assert update_mirror_images._parse_refresh("all") == "all"
        assert update_mirror_images._parse_refresh(" datadog/agent:latest , redis:7 ") == {
            "datadog/agent:latest",
            "redis:7",
        }

    @pytest.mark.parametrize("value", ["", " , ", "all,datadog/agent:latest"])
    def test_parse_refresh_rejects_invalid_values(self, value: str):
        with pytest.raises(ValueError):
            update_mirror_images._parse_refresh(value)

    def test_refresh_lock_entries_removes_matching_images(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch):
        lock_path = tmp_path / "mirror_images.lock.yaml"
        original_lock = _write_lock(lock_path)
        monkeypatch.setattr(update_mirror_images, "LOCK_YAML", lock_path)

        restored_lock = update_mirror_images._refresh_lock_entries({"datadog/agent:latest", "missing:latest"})

        assert restored_lock == original_lock
        data = yaml.safe_load(lock_path.read_text(encoding="utf-8"))
        assert sorted(data["images"]) == ["redis:7"]

    def test_refresh_lock_entries_all_removes_every_image(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch):
        lock_path = tmp_path / "mirror_images.lock.yaml"
        original_lock = _write_lock(lock_path)
        monkeypatch.setattr(update_mirror_images, "LOCK_YAML", lock_path)

        restored_lock = update_mirror_images._refresh_lock_entries("all")

        assert restored_lock == original_lock
        data = yaml.safe_load(lock_path.read_text(encoding="utf-8"))
        assert data["images"] == {}

    def test_main_refreshes_lock_before_lock_command(self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch):
        lock_path = tmp_path / "mirror_images.lock.yaml"
        mirror_yaml = tmp_path / "mirror_images.yaml"
        buildkitd_toml = tmp_path / "buildkitd.toml"
        _write_lock(lock_path)
        calls: list[tuple[str, ...]] = []

        monkeypatch.chdir(tmp_path)
        monkeypatch.setattr(update_mirror_images, "REPO_ROOT", tmp_path)
        monkeypatch.setattr(update_mirror_images, "LOCK_YAML", lock_path)
        monkeypatch.setattr(update_mirror_images, "MIRROR_YAML", mirror_yaml)
        monkeypatch.setattr(update_mirror_images, "BUILDKITD_TOML", buildkitd_toml)

        def fake_collect_images(excluded: set[str]) -> list[str]:
            assert excluded == {"SKIP_ME"}
            return ["datadog/agent:latest"]

        monkeypatch.setattr(update_mirror_images, "collect_images", fake_collect_images)

        def fake_run_mirror_images(*args: str) -> None:
            calls.append(args)
            if args == ("lock",):
                data = yaml.safe_load(lock_path.read_text(encoding="utf-8"))
                assert "datadog/agent:latest" not in data["images"]

        monkeypatch.setattr(update_mirror_images, "_run_mirror_images", fake_run_mirror_images)

        update_mirror_images.main({"SKIP_ME"}, skip_lock=False, refresh={"datadog/agent:latest"})

        assert calls == [
            ("add", "datadog/agent:latest"),
            ("lock",),
            ("buildkitd", "--output", str(buildkitd_toml)),
        ]
